import {api,session,mediaUrl} from './lib/api.js';
const app=document.querySelector('#app');
const state={me:null,workspace:null,shop:null,products:[],categories:[],orders:[],orderMetrics:null,orderStatus:'all',orderQuery:'',route:'overview',query:'',categoryId:'',status:'all',selected:new Set(),storefront:null,versions:[],telegram:null,customers:[],customerMetrics:null,customerQuery:'',customerSegment:'all',campaigns:[],campaignStatus:'all',automations:[],automationFilter:'all',analytics:null,analyticsDays:30,shops:[],team:null,payments:[],paymentStatus:'all',inventory:[],warehouseMetrics:null,warehouseMovements:[],warehouseType:'all',deliveryMethods:[],shipments:[],themePresets:[]};
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const root=()=>`/workspaces/${state.workspace.id}/shops/${state.shop.id}`;
const fileToBase64=file=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file)});
const fileToDataUrl=file=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=reject;reader.readAsDataURL(file)});
const icon=name=>`<span class="ico">${({home:'◈',catalog:'◇',orders:'◎',store:'▣',customers:'♧',campaigns:'✦',automations:'⌁',analytics:'◒',settings:'⚙'})[name]||'•'}</span>`;
const title=()=>({overview:'Обзор бизнеса',catalog:'Каталог',orders:'Заказы',customers:'Клиенты',storefront:'Конструктор витрины',campaigns:'Кампании',automations:'Автоматизации',analytics:'Аналитика',team:'Команда',payments:'Платежи',warehouse:'Склад',delivery:'Доставка',settings:'Настройки'})[state.route];
function shell(content){return `<div class="aurora"></div><aside class="sidebar"><div class="brand"><b>GT</b><span>STORE</span></div><nav>${[['overview','home','Обзор'],['catalog','catalog','Каталог'],['orders','orders','Заказы'],['customers','customers','Клиенты'],['campaigns','campaigns','Кампании'],['automations','automations','Автоматизации'],['analytics','analytics','Аналитика'],['team','settings','Команда'],['payments','orders','Платежи'],['warehouse','catalog','Склад'],['delivery','orders','Доставка'],['storefront','store','Витрина'],['settings','settings','Настройки']].map(([r,i,l])=>`<button data-route="${r}" class="nav ${state.route===r?'active':''}">${icon(i)}${l}</button>`).join('')}</nav><div class="side-foot"><span class="pulse"></span>Warehouse Core v6.17 · Delivery Core v6.18 · Theme Builder v6.19</div></aside><main><header><div><small>РАБОЧЕЕ ПРОСТРАНСТВО</small><h1>${title()}</h1></div><div class="top-actions"><select id="shop-switcher">${state.shops.map(s=>`<option value="${s.id}" ${state.shop?.id===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select><button class="ghost" id="command">⌘ K</button><div class="avatar">КЕ</div></div></header><section class="content">${content}</section></main>`}
function login(){app.innerHTML=`<div class="login"><div class="login-card"><div class="brand big"><b>GT</b><span>STORE</span></div><h1>Вход в платформу</h1><p>Production foundation для Telegram, MAX и Web.</p><form id="login"><label>Email<input name="email" value="owner@gtstore.local"></label><label>Пароль<input name="password" type="password" value="ChangeMe123!"></label><button class="primary">Войти</button><button type="button" class="ghost wide" id="bootstrap">Создать демо-пространство</button><div id="error"></div></form></div></div>`;document.querySelector('#login').onsubmit=async e=>{e.preventDefault();try{const data=await api('/auth/login',{method:'POST',body:Object.fromEntries(new FormData(e.currentTarget))});session.token=data.token;await load();}catch(err){document.querySelector('#error').textContent=err.message}};document.querySelector('#bootstrap').onclick=async()=>{try{await api('/bootstrap',{method:'POST',body:{email:'owner@gtstore.local',password:'ChangeMe123!',name:'Кирилл'}});document.querySelector('#error').textContent='Готово. Теперь нажмите «Войти».'}catch(err){document.querySelector('#error').textContent=err.message}}}
async function load(){try{state.me=await api('/me');state.workspace=state.me.workspaces[0];state.shops=await api(`/workspaces/${state.workspace.id}/shops`);state.shop=state.shop&&state.shops.find(s=>s.id===state.shop.id)||state.shops[0];await Promise.all([loadCatalog(),loadOrders(),loadCustomers(),loadCampaigns()]);render()}catch{session.token='';login()}}
async function loadCatalog(){if(!state.shop)return;const params=new URLSearchParams({q:state.query,status:state.status});if(state.categoryId)params.set('categoryId',state.categoryId);[state.categories,state.products]=await Promise.all([api(root()+'/categories'),api(root()+'/products?'+params)]);state.selected.clear()}
function overview(){return `<div class="hero"><div><span class="eyebrow">VISION COMMERCE OS</span><h2>Каталог, который растёт<br><em>вместе с бизнесом.</em></h2><p>Категории, вариации, изображения, массовые действия и импорт.</p><button class="primary" data-route="catalog">Открыть каталог →</button></div><div class="orb"><span>${state.products.length}</span><small>товаров</small></div></div><div class="metrics">${[['Товары',state.products.length,'В текущем магазине'],['Категории',state.categories.length,'Структура каталога'],['Остатки',state.products.reduce((s,p)=>s+(p.totalStock??p.stock),0),'Единиц на складе'],['Активные',state.products.filter(p=>p.active).length,'Опубликованы']].map(([a,b,c])=>`<article><small>${a}</small><strong>${b}</strong><span>${c}</span></article>`).join('')}</div>`}
function categoryOptions(selected=''){return `<option value="">Без категории</option>${state.categories.map(c=>`<option value="${c.id}" ${selected===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}`}
function catalog(){return `<div class="catalog-layout"><aside class="category-panel panel"><div class="panel-head"><h3>Категории</h3><button class="icon-btn" id="new-category">+</button></div><button class="category-item ${!state.categoryId?'active':''}" data-category="">Все товары <span>${state.products.length}</span></button>${state.categories.map(c=>`<button class="category-item ${state.categoryId===c.id?'active':''}" data-category="${c.id}">${esc(c.name)}</button>`).join('')}</aside><div class="catalog-main"><div class="toolbar"><div class="search">⌕ <input id="search" value="${esc(state.query)}" placeholder="Поиск по названию, SKU или бренду"></div><select id="status"><option value="all">Все статусы</option><option value="active" ${state.status==='active'?'selected':''}>Активные</option><option value="hidden" ${state.status==='hidden'?'selected':''}>Скрытые</option></select><button class="ghost" id="import">Импорт</button><button class="primary" id="new-product">+ Новый товар</button></div>${state.selected.size?`<div class="bulkbar"><b>Выбрано: ${state.selected.size}</b><button class="ghost" data-bulk="show">Опубликовать</button><button class="ghost" data-bulk="hide">Скрыть</button><button class="ghost" data-bulk="stock">+10 к остатку</button></div>`:''}<div class="panel table"><div class="row head product-row"><span><input type="checkbox" id="select-all"></span><span>Товар</span><span>SKU</span><span>Цена</span><span>Остаток</span><span>Статус</span><span></span></div>${state.products.length?state.products.map(p=>`<div class="row product-row"><span><input type="checkbox" data-select="${p.id}" ${state.selected.has(p.id)?'checked':''}></span><span class="product-name"><div class="thumb">${mediaUrl(p.images?.[0]?.url)?`<img src="${esc(mediaUrl(p.images[0].url))}">`:'◇'}</div><span><b>${esc(p.name)}</b><small>${esc(p.brand||'Без бренда')} · ${p.variants?.length||0} вариаций</small></span></span><span class="mono">${esc(p.sku)}</span><span>${Number(p.price).toLocaleString('ru-RU')} ₽</span><span>${p.totalStock??p.stock}</span><span><i class="status">${p.active?'Активен':'Скрыт'}</i></span><span class="actions"><button class="icon-btn" data-edit="${p.id}">✎</button><button class="icon-btn danger" data-delete="${p.id}">×</button></span></div>`).join(''):`<div class="empty"><div>◇</div><h3>Ничего не найдено</h3><p>Измените фильтры или создайте первый товар.</p></div>`}</div></div></div>`}
async function loadTelegram(){state.telegram=await api(root()+'/telegram')}
function telegramSettings(){const c=state.telegram||{connected:false,enabled:false,adminChatId:'',botUsername:'',webhookUrl:'',lastError:''};return `<div class="panel telegram-settings"><div class="panel-head"><div><small>TELEGRAM BOT API</small><h2>${c.connected?'Подключён @'+esc(c.botUsername):'Подключение Telegram'}</h2></div><i class="status">${c.connected?'Активен':'Не подключён'}</i></div><form id="telegram-form" class="form-grid"><label class="full">Токен BotFather<input name="token" type="password" placeholder="123456789:AA..." ${c.connected?'':'required'}></label><label>Chat ID администратора<input name="adminChatId" value="${esc(c.adminChatId)}" placeholder="-1001234567890" required></label><label>Webhook URL<input name="webhookUrl" value="${esc(c.webhookUrl)}" placeholder="https://domain.ru/api/v6/telegram/webhook/..." ></label><label class="full">Webhook secret<input name="webhookSecret" placeholder="Секрет для проверки запросов Telegram"></label><label class="check full"><input name="enabled" type="checkbox" ${c.enabled?'checked':''}> Отправлять уведомления о новых заказах</label><div class="full modal-actions"><button class="primary">${c.connected?'Обновить подключение':'Подключить бота'}</button>${c.connected?'<button type="button" class="ghost" id="telegram-test">Тестовое сообщение</button><button type="button" class="ghost danger" id="telegram-disconnect">Отключить</button>':''}</div><div class="form-error full">${esc(c.lastError||'')}</div></form><div class="panel telegram-help"><h3>Что работает</h3><p>Новые заказы автоматически отправляются администратору. В карточке заказа есть inline-кнопки изменения статуса. Токен хранится в зашифрованном виде AES-256-GCM и не возвращается в браузер.</p></div></div>`}
function bindTelegram(){const form=document.querySelector('#telegram-form');form.onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(form));data.enabled=form.enabled.checked;if(!data.token&&state.telegram?.connected){form.querySelector('.form-error').textContent='Для обновления подключения повторно укажите токен.';return}try{state.telegram=await api(root()+'/telegram/connect',{method:'POST',body:data});render()}catch(err){form.querySelector('.form-error').textContent=err.message}};const test=document.querySelector('#telegram-test');if(test)test.onclick=async()=>{try{await api(root()+'/telegram/test',{method:'POST'});alert('Тестовое сообщение отправлено')}catch(err){alert(err.message)}};const disconnect=document.querySelector('#telegram-disconnect');if(disconnect)disconnect.onclick=async()=>{if(confirm('Отключить Telegram-бота?')){await api(root()+'/telegram',{method:'DELETE'});await loadTelegram();render()}}}

async function loadAutomations(){if(!state.shop)return;state.automations=await api(root()+'/automations')}
const automationTriggerLabels={order_created:'Новый заказ',order_status_changed:'Статус заказа'};
const orderStatusLabels={new:'Новый',confirmed:'Подтверждён',awaiting_payment:'Ожидает оплату',paid:'Оплачен',assembling:'Собирается',ready:'Готов',shipped:'Передан в доставку',completed:'Завершён',cancelled:'Отменён',refunded:'Возврат'};
function automationsPage(){const items=state.automations.filter(r=>state.automationFilter==='all'||(state.automationFilter==='enabled'?r.enabled!==false:r.enabled===false));const totals=state.automations.reduce((a,r)=>{a.total+=Number(r.metrics?.total||0);a.sent+=Number(r.metrics?.sent||0);a.failed+=Number(r.metrics?.failed||0);a.pending+=Number(r.metrics?.pending||0);return a},{total:0,sent:0,failed:0,pending:0});return `<div class="campaign-head"><div><span class="eyebrow">TRIGGERED COMMERCE</span><h2>Automation Studio</h2><p>Настраивайте автоматические Telegram-сообщения после заказа и при изменении его статуса.</p></div><button class="primary" id="new-automation">+ Новый сценарий</button></div><div class="metrics campaign-metrics">${[['Сценариев',state.automations.length,'Всего правил'],['В очереди',totals.pending,'Ожидают отправки'],['Отправлено',totals.sent,'Успешные сообщения'],['Ошибки',totals.failed,'Не доставлено']].map(([a,b,c])=>`<article><small>${a}</small><strong>${b}</strong><span>${c}</span></article>`).join('')}</div><div class="toolbar"><select id="automation-filter"><option value="all">Все сценарии</option><option value="enabled" ${state.automationFilter==='enabled'?'selected':''}>Включённые</option><option value="disabled" ${state.automationFilter==='disabled'?'selected':''}>Выключенные</option></select><button class="ghost" id="refresh-automations">Обновить</button></div><div class="automation-grid">${items.length?items.map(r=>`<article class="automation-card"><div class="automation-card-top"><span class="automation-state ${r.enabled!==false?'on':'off'}">${r.enabled!==false?'Активен':'Выключен'}</span><button class="icon-button" data-automation-menu="${r.id}">•••</button></div><h3>${esc(r.name)}</h3><div class="automation-flow"><span>${automationTriggerLabels[r.trigger]||r.trigger}${r.status?`: ${orderStatusLabels[r.status]||r.status}`:''}</span><b>→</b><span>${r.delayMinutes?`Через ${r.delayMinutes} мин.`:'Сразу'}</span><b>→</b><span>Telegram</span></div><p>${esc(r.message)}</p><div class="automation-stats"><span><b>${r.metrics?.sent||0}</b> отправлено</span><span><b>${r.metrics?.pending||0}</b> в очереди</span><span><b>${r.metrics?.failed||0}</b> ошибок</span></div><div class="automation-actions"><button class="ghost" data-automation-view="${r.id}">Журнал</button><button class="ghost" data-automation-edit="${r.id}">Изменить</button><label class="switch"><input type="checkbox" data-automation-toggle="${r.id}" ${r.enabled!==false?'checked':''}><span></span></label></div></article>`).join(''):`<div class="panel empty"><div>⌁</div><h2>Сценариев пока нет</h2><p>Создайте первое автоматическое сообщение для покупателей.</p></div>`}</div>`}
function automationEditor(rule={}){const modal=document.createElement('div');modal.className='modal-wrap';modal.innerHTML=`<div class="modal automation-modal"><button class="modal-close">×</button><span class="eyebrow">AUTOMATION FLOW</span><h2>${rule.id?'Редактирование сценария':'Новый сценарий'}</h2><form id="automation-form"><label>Название<input name="name" required value="${esc(rule.name||'')}"></label><div class="form-grid"><label>Триггер<select name="trigger" id="automation-trigger"><option value="order_created" ${rule.trigger==='order_created'?'selected':''}>Создан новый заказ</option><option value="order_status_changed" ${rule.trigger==='order_status_changed'?'selected':''}>Изменился статус заказа</option></select></label><label id="automation-status-wrap">Статус<select name="status">${Object.entries(orderStatusLabels).map(([k,v])=>`<option value="${k}" ${rule.status===k?'selected':''}>${v}</option>`).join('')}</select></label></div><label>Задержка, минут<input name="delayMinutes" type="number" min="0" max="10080" value="${Number(rule.delayMinutes||0)}"></label><label>Сообщение<textarea name="message" rows="7" required>${esc(rule.message||'Здравствуйте, {{customer.name}}! Заказ №{{order.number}} принят.')}</textarea></label><div class="variable-row"><button type="button" data-var="{{customer.name}}">Имя</button><button type="button" data-var="{{order.number}}">Номер заказа</button><button type="button" data-var="{{order.total}}">Сумма</button><button type="button" data-var="{{order.status}}">Статус</button></div><label class="check-line"><input type="checkbox" name="enabled" ${rule.enabled!==false?'checked':''}> Сценарий включён</label><div class="form-error"></div><div class="modal-actions"><button type="button" class="ghost modal-cancel">Отмена</button><button class="primary">Сохранить сценарий</button></div></form></div>`;document.body.append(modal);const close=()=>modal.remove();modal.querySelector('.modal-close').onclick=close;modal.querySelector('.modal-cancel').onclick=close;const trigger=modal.querySelector('#automation-trigger'),wrap=modal.querySelector('#automation-status-wrap');const sync=()=>wrap.style.display=trigger.value==='order_status_changed'?'grid':'none';trigger.onchange=sync;sync();modal.querySelectorAll('[data-var]').forEach(b=>b.onclick=()=>{const t=modal.querySelector('[name="message"]');t.setRangeText(b.dataset.var,t.selectionStart,t.selectionEnd,'end');t.focus()});modal.querySelector('#automation-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,d=Object.fromEntries(new FormData(f));d.delayMinutes=Number(d.delayMinutes||0);d.enabled=f.enabled.checked;if(d.trigger!=='order_status_changed')d.status=null;try{if(rule.id)await api(root()+'/automations/'+rule.id,{method:'PATCH',body:d});else await api(root()+'/automations',{method:'POST',body:d});await loadAutomations();close();render()}catch(err){f.querySelector('.form-error').textContent=err.message}}}
async function automationDetails(id){const rule=await api(root()+'/automations/'+id);const modal=document.createElement('div');modal.className='modal-wrap';modal.innerHTML=`<div class="modal automation-modal wide"><button class="modal-close">×</button><span class="eyebrow">EXECUTION LOG</span><h2>${esc(rule.name)}</h2><div class="run-list">${rule.runs?.length?rule.runs.map(run=>`<div class="run-row"><span class="status status-${run.status}">${run.status}</span><div><b>Заказ ${esc(run.orderId)}</b><small>${new Date(run.createdAt).toLocaleString('ru-RU')} · ${esc(run.telegramId)}</small></div><p>${esc(run.message)}</p><small>${run.reason?esc(run.reason):run.sentAt?'Отправлено '+new Date(run.sentAt).toLocaleString('ru-RU'):'Запланировано '+new Date(run.scheduledAt).toLocaleString('ru-RU')}</small></div>`).join(''):'<div class="empty"><p>Запусков ещё не было.</p></div>'}</div></div>`;document.body.append(modal);modal.querySelector('.modal-close').onclick=()=>modal.remove()}
function bindAutomations(){document.querySelector('#new-automation').onclick=()=>automationEditor();document.querySelector('#refresh-automations').onclick=async()=>{await loadAutomations();render()};document.querySelector('#automation-filter').onchange=e=>{state.automationFilter=e.target.value;render()};document.querySelectorAll('[data-automation-edit]').forEach(el=>el.onclick=()=>automationEditor(state.automations.find(r=>r.id===el.dataset.automationEdit)));document.querySelectorAll('[data-automation-view]').forEach(el=>el.onclick=()=>automationDetails(el.dataset.automationView));document.querySelectorAll('[data-automation-toggle]').forEach(el=>el.onchange=async()=>{await api(root()+'/automations/'+el.dataset.automationToggle,{method:'PATCH',body:{enabled:el.checked}});await loadAutomations();render()});document.querySelectorAll('[data-automation-menu]').forEach(el=>el.onclick=async()=>{const rule=state.automations.find(r=>r.id===el.dataset.automationMenu);if(confirm(`Удалить сценарий «${rule.name}»?`)){await api(root()+'/automations/'+rule.id,{method:'DELETE'});await loadAutomations();render()}})}

function placeholder(){return `<div class="panel empty"><div>✦</div><h2>${title()}</h2><p>Модуль подключён к новой навигации и будет развиваться следующим спринтом.</p></div>`}
function render(){app.innerHTML=shell(state.route==='overview'?overview():state.route==='catalog'?catalog():state.route==='orders'?ordersPage():state.route==='customers'?customersPage():state.route==='campaigns'?campaignsPage():state.route==='automations'?automationsPage():state.route==='analytics'?analyticsPage():state.route==='team'?teamPage():state.route==='payments'?paymentsPage():state.route==='warehouse'?warehousePage():state.route==='delivery'?deliveryPage():state.route==='storefront'?storefrontBuilder():state.route==='settings'?telegramSettings():placeholder());document.querySelectorAll('[data-route]').forEach(el=>el.onclick=async()=>{state.route=el.dataset.route;if(state.route==='storefront')await loadStorefront();if(state.route==='customers')await loadCustomers();if(state.route==='orders')await loadOrders();if(state.route==='campaigns')await loadCampaigns();if(state.route==='automations')await loadAutomations();if(state.route==='analytics')await loadAnalytics();if(state.route==='team')await loadTeam();if(state.route==='payments')await loadPayments();if(state.route==='warehouse')await loadWarehouse();if(state.route==='delivery')await loadDelivery();if(state.route==='settings')await loadTelegram();render()});if(state.route==='catalog')bindCatalog();if(state.route==='orders')bindOrders();if(state.route==='customers')bindCustomers();if(state.route==='campaigns')bindCampaigns();if(state.route==='automations')bindAutomations();if(state.route==='analytics')bindAnalytics();if(state.route==='team')bindTeam();if(state.route==='payments')bindPayments();if(state.route==='warehouse')bindWarehouse();if(state.route==='delivery')bindDelivery();if(state.route==='storefront')bindStorefront();if(state.route==='settings')bindTelegram()}
function bindCatalog(){document.querySelector('#new-product').onclick=()=>productModal();document.querySelector('#new-category').onclick=categoryModal;document.querySelector('#import').onclick=importModal;document.querySelector('#search').oninput=e=>{clearTimeout(bindCatalog.t);bindCatalog.t=setTimeout(async()=>{state.query=e.target.value;await loadCatalog();render()},250)};document.querySelector('#status').onchange=async e=>{state.status=e.target.value;await loadCatalog();render()};document.querySelectorAll('[data-category]').forEach(el=>el.onclick=async()=>{state.categoryId=el.dataset.category;await loadCatalog();render()});document.querySelectorAll('[data-select]').forEach(el=>el.onchange=()=>{el.checked?state.selected.add(el.dataset.select):state.selected.delete(el.dataset.select);render()});const all=document.querySelector('#select-all');if(all)all.onchange=()=>{state.selected=new Set(all.checked?state.products.map(p=>p.id):[]);render()};document.querySelectorAll('[data-edit]').forEach(el=>el.onclick=()=>productModal(state.products.find(p=>p.id===el.dataset.edit)));document.querySelectorAll('[data-delete]').forEach(el=>el.onclick=async()=>{if(confirm('Удалить товар без возможности восстановления?')){await api(root()+`/products/${el.dataset.delete}`,{method:'DELETE'});await loadCatalog();render()}});document.querySelectorAll('[data-bulk]').forEach(el=>el.onclick=async()=>{const action=el.dataset.bulk;const body={ids:[...state.selected]};if(action==='show')body.active=true;if(action==='hide')body.active=false;if(action==='stock')body.stockDelta=10;await api(root()+'/products/bulk',{method:'POST',body});await loadCatalog();render()})}
function modal(title,fields,onSubmit,size=''){const wrap=document.createElement('div');wrap.className='modal-wrap';wrap.innerHTML=`<form class="modal ${size}"><div class="panel-head"><h2>${title}</h2><button type="button" class="x">×</button></div>${fields}<div class="modal-actions"><button type="button" class="ghost cancel">Отмена</button><button class="primary">Сохранить</button></div><div class="form-error"></div></form>`;document.body.append(wrap);wrap.querySelectorAll('.x,.cancel').forEach(b=>b.onclick=()=>wrap.remove());wrap.querySelector('form').onsubmit=async e=>{e.preventDefault();try{await onSubmit(e.currentTarget);wrap.remove();await loadCatalog();render()}catch(err){wrap.querySelector('.form-error').textContent=err.message}};return wrap}
function productModal(product=null){
 const variants=structuredClone(product?.variants||[]);const images=structuredClone(product?.images||[]);
 const wrap=modal(product?'Редактирование товара':'Новый товар',`<div class="form-grid"><label class="full">Название<input name="name" value="${esc(product?.name||'')}" required></label><label>SKU<input name="sku" value="${esc(product?.sku||'')}" required></label><label>Бренд<input name="brand" value="${esc(product?.brand||'')}"></label><label>Категория<select name="categoryId">${categoryOptions(product?.categoryId)}</select></label><label>Цена<input name="price" type="number" min="0" step="0.01" value="${product?.price??''}" required></label><label>Остаток<input name="stock" type="number" min="0" value="${product?.stock??0}" required></label><div class="full media-editor"><div class="variants-head"><div><h3>Медиагалерея</h3><p class="muted">JPEG, PNG, WebP или GIF, до 8 МБ. Первое изображение — обложка.</p></div><label class="ghost upload-button">+ Загрузить<input id="media-files" type="file" accept="image/jpeg,image/png,image/webp,image/gif" multiple hidden></label></div><div id="media-gallery" class="media-gallery"></div></div><label class="full">Описание<textarea name="description">${esc(product?.description||'')}</textarea></label><div class="full variants-head"><h3>Вариации</h3><button type="button" class="ghost" id="add-variant">+ Вариация</button></div><div class="full" id="variants"></div></div>`,async form=>{const data=Object.fromEntries(new FormData(form));data.images=images.map((image,index)=>({...image,position:index,primary:index===0}));data.variants=[...form.querySelectorAll('.variant-row')].map(row=>Object.fromEntries(new FormData(row)));const path=product?root()+`/products/${product.id}`:root()+'/products';await api(path,{method:product?'PATCH':'POST',body:data})},'large');
 const gallery=wrap.querySelector('#media-gallery');
 const drawImages=()=>{gallery.innerHTML=images.length?images.map((image,index)=>`<article class="media-card"><img src="${esc(mediaUrl(image.url))}" alt=""><span>${index===0?'Обложка':`Фото ${index+1}`}</span><div><button type="button" class="icon-btn" data-left="${index}" ${index===0?'disabled':''}>←</button><button type="button" class="icon-btn" data-right="${index}" ${index===images.length-1?'disabled':''}>→</button><button type="button" class="icon-btn danger" data-remove-image="${index}">×</button></div></article>`).join(''):`<div class="media-empty">Перетащите или выберите изображения</div>`;gallery.querySelectorAll('[data-remove-image]').forEach(button=>button.onclick=()=>{images.splice(Number(button.dataset.removeImage),1);drawImages()});gallery.querySelectorAll('[data-left]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.left);[images[i-1],images[i]]=[images[i],images[i-1]];drawImages()});gallery.querySelectorAll('[data-right]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.right);[images[i+1],images[i]]=[images[i],images[i+1]];drawImages()})};drawImages();
 wrap.querySelector('#media-files').onchange=async event=>{const input=event.target;for(const file of input.files){const dataUrl=await fileToDataUrl(file);const uploaded=await api(root()+'/media',{method:'POST',body:{dataUrl,originalName:file.name,alt:product?.name||''}});images.push(uploaded)}drawImages();input.value=''};
 const box=wrap.querySelector('#variants');const draw=()=>{box.innerHTML=variants.map((v,i)=>`<div class="variant-row"><input name="name" value="${esc(v.name||'')}" placeholder="Название"><input name="sku" value="${esc(v.sku||'')}" placeholder="SKU"><input name="price" type="number" value="${v.price??0}" placeholder="Цена"><input name="stock" type="number" value="${v.stock??0}" placeholder="Остаток"><button type="button" class="icon-btn danger" data-remove="${i}">×</button></div>`).join('');box.querySelectorAll('[data-remove]').forEach(btn=>btn.onclick=()=>{variants.splice(Number(btn.dataset.remove),1);draw()})};draw();wrap.querySelector('#add-variant').onclick=()=>{variants.push({name:'',sku:'',price:0,stock:0});draw()}}
function categoryModal(){modal('Новая категория',`<label>Название<input name="name" required></label><label>Родительская категория<select name="parentId">${categoryOptions()}</select></label>`,async form=>api(root()+'/categories',{method:'POST',body:Object.fromEntries(new FormData(form))}))}
function importModal(){
 let uploaded=null,preview=null,busy=false;
 const errorMessage=error=>[error?.message||'Не удалось обработать файл. Попробуйте выбрать его ещё раз.',...(Array.isArray(error?.details)?error.details.slice(0,20).map(item=>item.message||item.error||'').filter(Boolean):[])].join('\n');
 const wrap=modal('Центр импорта',`<div class="import-steps"><b>1. Файл</b><span>2. Проверка</span><span>3. Импорт</span></div><label class="import-drop">Выберите CSV или Excel<input name="file" type="file" accept=".csv,.xlsx,.xls" required><small>Фотографии будут сохранены на сервере. Товары с совпадающим SKU будут обновлены.</small></label><label class="checkline"><input name="skipInvalid" type="checkbox"> Пропустить некорректные строки при подтверждении</label><p id="import-status" role="status" aria-live="polite"></p><div id="preview-result" class="import-preview"></div>`,async form=>{
   if(!uploaded||!preview)throw new Error('Сначала выберите файл и дождитесь проверки.');
   if(!preview.valid&&!form.elements.skipInvalid.checked)throw new Error('Исправьте ошибки файла или включите пропуск некорректных строк.');
   setBusy(true,'Сохраняем товары и фотографии на сервере. Дождитесь завершения.');
   try{
     const result=await api(root()+'/import/commit',{method:'POST',body:{...uploaded,options:{skipInvalid:form.elements.skipInvalid.checked,updateExisting:true}}});
     const summary=`Обработано товаров: ${result.imported}. Создано: ${result.created??result.imported}, обновлено: ${result.updated??0}. Ошибок: ${result.failed}.`;
     if(result.failed){
       await loadCatalog();render();
       const details=(result.errors||[]).slice(0,20).map(item=>`${item.sku||'Строка '+item.line}: ${item.message||item.error||'Ошибка импорта'}`);
       throw new Error([summary,...details].join('\n'));
     }
     alert(`Импорт завершён. ${summary}`);
   }catch(error){throw new Error(errorMessage(error));}
   finally{setBusy(false);}
 },'large');
 const file=wrap.querySelector('[name=file]'),resultBox=wrap.querySelector('#preview-result'),status=wrap.querySelector('#import-status'),form=wrap.querySelector('form'),submit=wrap.querySelector('.modal-actions .primary');
 const setBusy=(value,message='')=>{busy=value;file.disabled=value;submit.disabled=value||!preview;submit.textContent=value?'Подождите…':'Импортировать';status.textContent=message;wrap.querySelectorAll('.x,.cancel,[name=skipInvalid]').forEach(button=>button.disabled=value);};
 wrap.querySelector('.form-error').style.whiteSpace='pre-line';
 const onSubmit=form.onsubmit;
 form.onsubmit=event=>{if(busy){event.preventDefault();return;}return onSubmit(event);};
 setBusy(false);
 const showPreview=()=>{resultBox.innerHTML=`<div class="import-summary ${preview.valid?'ok':'bad'}"><b>${preview.valid?'Файл прошёл проверку':'Найдены ошибки'}</b><span>Товаров: ${preview.total} · Ошибок: ${preview.errors.length} · Предупреждений: ${preview.warnings.length}</span><span>Листы: ${preview.sheets.map(sheet=>`${esc(sheet.name)} (${sheet.rows})`).join(', ')}</span>${Number.isFinite(preview.uniqueImages)?`<span>Уникальных фотографий для сохранения: ${preview.uniqueImages}</span>`:''}</div>${preview.errors.length?`<div class="import-errors">${preview.errors.slice(0,20).map(error=>`<p>Строка ${error.line}: ${esc(error.message)}</p>`).join('')}</div>`:''}<div class="import-table">${preview.rows.slice(0,8).map(row=>`<div><b>${esc(row.name||'Без названия')}</b><span>${esc(row.sku||'Без SKU')}</span><span>${esc(row.price||0)} ₽</span></div>`).join('')}</div>`};
 file.onchange=async()=>{
   if(busy)return;
   uploaded=null;preview=null;resultBox.textContent='';wrap.querySelector('.form-error').textContent='';
   const selected=file.files[0];
   if(!selected){setBusy(false);return;}
   setBusy(true,'Читаем файл и проверяем товары…');
   try{
     const candidate={filename:selected.name,base64:await fileToBase64(selected)};
     preview=await api(root()+'/import/file',{method:'POST',body:candidate});
     uploaded=candidate;
     showPreview();
   }catch(error){wrap.querySelector('.form-error').textContent=errorMessage(error);}
   finally{setBusy(false);}
 };
}


async function loadOrders(){if(!state.shop)return;const params=new URLSearchParams({q:state.orderQuery,status:state.orderStatus});[state.orders,state.orderMetrics]=await Promise.all([api(root()+'/orders?'+params),api(root()+'/orders/metrics')])}
const orderStatusName={new:'Новый',confirmed:'Подтверждён',awaiting_payment:'Ожидает оплату',paid:'Оплачен',assembling:'Собирается',ready:'Готов',shipped:'Передан в доставку',completed:'Завершён',cancelled:'Отменён',refunded:'Возврат'};
function ordersPage(){const m=state.orderMetrics||{total:0,new:0,processing:0,revenue:0,average:0};return `<div class="metrics">${[['Заказы',m.total,'За всё время'],['Новые',m.new,'Требуют внимания'],['В работе',m.processing,'Активные статусы'],['Выручка',Number(m.revenue).toLocaleString('ru-RU')+' ₽','Оплаченные заказы']].map(([a,b,c])=>`<article><small>${a}</small><strong>${b}</strong><span>${c}</span></article>`).join('')}</div><div class="toolbar"><div class="search">⌕ <input id="order-search" value="${esc(state.orderQuery)}" placeholder="Номер, клиент или телефон"></div><select id="order-status"><option value="all">Все статусы</option>${Object.entries(orderStatusName).map(([v,l])=>`<option value="${v}" ${state.orderStatus===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="panel order-table"><div class="row order-row head"><span>Заказ</span><span>Клиент</span><span>Состав</span><span>Сумма</span><span>Оплата</span><span>Статус</span></div>${state.orders.length?state.orders.map(o=>`<button class="row order-row order-link" data-order="${o.id}"><span><b>№${esc(o.number)}</b><small>${new Date(o.createdAt).toLocaleString('ru-RU')}</small></span><span><b>${esc(o.customer.name)}</b><small>${esc(o.customer.phone)}</small></span><span>${o.lines.length} поз.</span><span><b>${Number(o.total).toLocaleString('ru-RU')} ₽</b></span><span><i class="status">${o.paymentStatus==='paid'?'Оплачен':'Ожидает'}</i></span><span><i class="status">${orderStatusName[o.status]||o.status}</i></span></button>`).join(''):`<div class="empty"><div>◎</div><h3>Заказов пока нет</h3><p>Оформите тестовый заказ через публичную витрину.</p></div>`}</div>`}
function bindOrders(){const search=document.querySelector('#order-search');if(search)search.oninput=e=>{clearTimeout(bindOrders.t);bindOrders.t=setTimeout(async()=>{state.orderQuery=e.target.value;await loadOrders();render()},250)};const status=document.querySelector('#order-status');if(status)status.onchange=async e=>{state.orderStatus=e.target.value;await loadOrders();render()};document.querySelectorAll('[data-order]').forEach(el=>el.onclick=()=>openOrder(el.dataset.order))}
async function openOrder(orderId){const o=await api(root()+`/orders/${orderId}`);const next={new:['confirmed','cancelled'],confirmed:['awaiting_payment','paid','assembling','cancelled'],awaiting_payment:['paid','cancelled'],paid:['assembling','refunded'],assembling:['ready','cancelled'],ready:['shipped','completed','cancelled'],shipped:['completed','refunded'],completed:['refunded'],cancelled:[],refunded:[]}[o.status]||[];const wrap=modal(`Заказ №${o.number}`,`<div class="order-detail"><section><h3>Покупатель</h3><p><b>${esc(o.customer.name)}</b><br>${esc(o.customer.phone)}${o.customer.email?'<br>'+esc(o.customer.email):''}</p><h3>Доставка</h3><p>${o.deliveryMethod==='courier'?'Курьер':'Самовывоз'}${o.address?'<br>'+esc(o.address):''}</p><h3>Комментарий</h3><p>${esc(o.comment||'Без комментария')}</p></section><section><h3>Состав заказа</h3>${o.lines.map(line=>`<div class="order-line"><span>${esc(line.name)}${line.variantName?' · '+esc(line.variantName):''} × ${line.quantity}</span><b>${Number(line.total).toLocaleString('ru-RU')} ₽</b></div>`).join('')}<hr><div class="order-line total"><span>Итого</span><b>${Number(o.total).toLocaleString('ru-RU')} ₽</b></div><label>Статус<select name="status"><option value="${o.status}">${orderStatusName[o.status]}</option>${next.map(v=>`<option value="${v}">${orderStatusName[v]}</option>`).join('')}</select></label><label>Оплата<select name="paymentStatus"><option value="pending" ${o.paymentStatus==='pending'?'selected':''}>Ожидает</option><option value="paid" ${o.paymentStatus==='paid'?'selected':''}>Оплачен</option><option value="refunded" ${o.paymentStatus==='refunded'?'selected':''}>Возврат</option></select></label><label>Внутренняя заметка<textarea name="internalNote">${esc(o.internalNote||'')}</textarea></label></section></div>`,async form=>{await api(root()+`/orders/${orderId}`,{method:'PATCH',body:Object.fromEntries(new FormData(form))});await loadOrders()},'large');return wrap}


async function loadCustomers(){if(!state.shop)return;const p=new URLSearchParams({q:state.customerQuery,segment:state.customerSegment});[state.customers,state.customerMetrics]=await Promise.all([api(root()+'/customers?'+p),api(root()+'/customers/metrics')])}
function customersPage(){const m=state.customerMetrics||{total:0,new:0,repeat:0,vip:0,ltv:0,bonusLiability:0};return `<div class="metrics">${[['Клиенты',m.total,'Единая база'],['Повторные',m.repeat,'2+ заказа'],['VIP',m.vip,'Приоритетный сегмент'],['Средний LTV',Number(m.ltv).toLocaleString('ru-RU')+' ₽','Выручка на клиента']].map(([a,b,c])=>`<article><small>${a}</small><strong>${b}</strong><span>${c}</span></article>`).join('')}</div><div class="toolbar"><div class="search">⌕ <input id="customer-search" value="${esc(state.customerQuery)}" placeholder="Имя, телефон, email или Telegram"></div><select id="customer-segment"><option value="all">Все сегменты</option><option value="new" ${state.customerSegment==='new'?'selected':''}>Новые</option><option value="repeat" ${state.customerSegment==='repeat'?'selected':''}>Повторные</option><option value="vip" ${state.customerSegment==='vip'?'selected':''}>VIP</option></select><div class="loyalty-total">Бонусов в обороте: <b>${Number(m.bonusLiability).toLocaleString('ru-RU')}</b></div></div><div class="panel customer-table"><div class="row customer-row head"><span>Клиент</span><span>Сегмент</span><span>Заказы</span><span>Выручка</span><span>Бонусы</span><span>Уровень</span></div>${state.customers.length?state.customers.map(c=>`<button class="row customer-row customer-link" data-customer="${encodeURIComponent(c.key)}"><span><b>${esc(c.name||'Без имени')}</b><small>${esc(c.phone||c.email||('@'+c.telegramId))}</small></span><span><i class="status">${c.segment==='vip'?'VIP':c.segment==='repeat'?'Повторный':'Новый'}</i></span><span>${c.orders}</span><span><b>${Number(c.totalSpend).toLocaleString('ru-RU')} ₽</b><small>Средний ${Number(c.averageCheck).toLocaleString('ru-RU')} ₽</small></span><span><b>${Number(c.bonusBalance).toLocaleString('ru-RU')}</b></span><span>${esc(c.tier)} · ${c.cashback}%</span></button>`).join(''):`<div class="empty"><div>♧</div><h3>Клиентов пока нет</h3><p>Клиент появляется автоматически после первого заказа.</p></div>`}</div>`}
function bindCustomers(){const q=document.querySelector('#customer-search');if(q)q.oninput=e=>{clearTimeout(bindCustomers.t);bindCustomers.t=setTimeout(async()=>{state.customerQuery=e.target.value;await loadCustomers();render()},250)};const seg=document.querySelector('#customer-segment');if(seg)seg.onchange=async e=>{state.customerSegment=e.target.value;await loadCustomers();render()};document.querySelectorAll('[data-customer]').forEach(el=>el.onclick=()=>openCustomer(decodeURIComponent(el.dataset.customer)))}
async function openCustomer(key){const c=await api(root()+`/customers/${encodeURIComponent(key)}`);const fields=`<div class="customer-detail"><section><h3>${esc(c.name||'Клиент')}</h3><p>${esc(c.phone||'')}${c.email?'<br>'+esc(c.email):''}${c.telegramId?'<br>Telegram ID: '+esc(c.telegramId):''}</p><div class="loyalty-card"><small>Бонусный баланс</small><strong>${Number(c.bonusBalance).toLocaleString('ru-RU')}</strong><span>${esc(c.tier)} · кэшбэк ${c.cashback}%</span></div><label>Сегмент<select name="segment"><option value="new" ${c.segment==='new'?'selected':''}>Новый</option><option value="repeat" ${c.segment==='repeat'?'selected':''}>Повторный</option><option value="vip" ${c.segment==='vip'?'selected':''}>VIP</option></select></label><label>Заметки<textarea name="notes">${esc(c.notes||'')}</textarea></label></section><section><h3>История заказов</h3>${c.orders.map(o=>`<div class="order-line"><span>№${esc(o.number)} · ${new Date(o.createdAt).toLocaleDateString('ru-RU')}</span><b>${Number(o.total).toLocaleString('ru-RU')} ₽</b></div>`).join('')||'<p class="muted">Нет заказов</p>'}<h3>Бонусные операции</h3>${c.ledger.map(x=>`<div class="order-line"><span>${esc(x.reason)}</span><b>${x.amount>0?'+':''}${Number(x.amount).toLocaleString('ru-RU')}</b></div>`).join('')||'<p class="muted">Нет операций</p>'}<div class="crm-actions"><button type="button" class="ghost" id="bonus-add">Начислить бонусы</button><button type="button" class="ghost" id="promo-create">Создать промокод</button></div></section></div>`;const wrap=modal('Карточка клиента',fields,async form=>{await api(root()+`/customers/${encodeURIComponent(key)}`,{method:'PATCH',body:Object.fromEntries(new FormData(form))});await loadCustomers()},'large');wrap.querySelector('#bonus-add').onclick=async()=>{const amount=prompt('Сумма бонусов. Для списания укажите отрицательное число:','500');if(amount)await api(root()+`/customers/${encodeURIComponent(key)}/bonus`,{method:'POST',body:{amount:Number(amount),reason:'Ручная корректировка'}});wrap.remove();await loadCustomers();render()};wrap.querySelector('#promo-create').onclick=async()=>{const discount=prompt('Скидка по персональному промокоду, %:','10');if(discount){const promo=await api(root()+`/customers/${encodeURIComponent(key)}/promos`,{method:'POST',body:{discount:Number(discount)}});alert(`Промокод: ${promo.code}`)}}}


async function loadCampaigns(){if(!state.shop)return;state.campaigns=await api(root()+'/campaigns')}
const campaignStatusLabels={draft:'Черновик',scheduled:'Запланирована',sending:'Отправляется',sent:'Отправлена',failed:'Ошибка',cancelled:'Отменена'};
const segmentLabels={all:'Все клиенты',new:'Новые',repeat:'Повторные',vip:'VIP'};
function campaignsPage(){const items=state.campaigns.filter(c=>state.campaignStatus==='all'||c.status===state.campaignStatus);const total=state.campaigns.length,sent=state.campaigns.reduce((n,c)=>n+Number(c.metrics?.sent||0),0),failed=state.campaigns.reduce((n,c)=>n+Number(c.metrics?.failed||0),0),scheduled=state.campaigns.filter(c=>c.status==='scheduled').length;return `<div class="campaign-head"><div><span class="eyebrow">CRM COMMUNICATIONS</span><h2>Campaign Studio</h2><p>Создавайте Telegram-рассылки по сегментам, планируйте отправку и контролируйте доставку.</p></div><button class="primary" id="new-campaign">+ Новая кампания</button></div><div class="metrics campaign-metrics">${[['Кампаний',total,'Всего создано'],['Запланировано',scheduled,'Ожидают запуска'],['Доставлено',sent,'Успешные сообщения'],['Ошибки',failed,'Не доставлено']].map(([a,b,c])=>`<article><small>${a}</small><strong>${b}</strong><span>${c}</span></article>`).join('')}</div><div class="toolbar"><select id="campaign-status"><option value="all">Все статусы</option>${Object.entries(campaignStatusLabels).map(([k,v])=>`<option value="${k}" ${state.campaignStatus===k?'selected':''}>${v}</option>`).join('')}</select><button class="ghost" id="refresh-campaigns">Обновить</button></div><div class="panel campaign-table"><div class="row head campaign-row"><span>Кампания</span><span>Сегмент</span><span>Статус</span><span>Результат</span><span>Запуск</span><span></span></div>${items.length?items.map(c=>`<button class="row campaign-row campaign-link" data-campaign="${c.id}"><span><b>${esc(c.name)}</b><small>${esc(c.message).slice(0,90)}${c.message.length>90?'…':''}</small></span><span>${segmentLabels[c.segment]||esc(c.segment)}</span><span><i class="status status-${c.status}">${campaignStatusLabels[c.status]||c.status}</i></span><span><b>${Number(c.metrics?.sent||0)}</b><small>ошибок: ${Number(c.metrics?.failed||0)}</small></span><span>${c.scheduledAt?new Date(c.scheduledAt).toLocaleString('ru-RU'):c.sentAt?new Date(c.sentAt).toLocaleString('ru-RU'):'—'}</span><span>→</span></button>`).join(''):`<div class="empty"><div>✦</div><h3>Кампаний пока нет</h3><p>Создайте первую рассылку по клиентской базе.</p></div>`}</div>`}
function campaignFields(c={}){const local=c.scheduledAt?new Date(new Date(c.scheduledAt).getTime()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16):'';return `<div class="form-grid"><label class="full">Название<input name="name" value="${esc(c.name||'')}" required maxlength="120"></label><label>Сегмент<select name="segment"><option value="all" ${c.segment==='all'?'selected':''}>Все клиенты</option><option value="new" ${c.segment==='new'?'selected':''}>Новые</option><option value="repeat" ${c.segment==='repeat'?'selected':''}>Повторные</option><option value="vip" ${c.segment==='vip'?'selected':''}>VIP</option></select></label><label>Дата и время отправки<input name="scheduledAt" type="datetime-local" value="${local}"></label><label class="full">Сообщение<textarea name="message" rows="8" maxlength="4096" required>${esc(c.message||'')}</textarea><small class="muted">До 4096 символов. Поддерживается обычный текст Telegram.</small></label></div>`}
function openCampaignEditor(c){const editable=!c||!['sending','sent','cancelled'].includes(c.status);const wrap=modal(c?'Кампания':'Новая кампания',editable?campaignFields(c):campaignDetails(c),async form=>{const data=Object.fromEntries(new FormData(form));data.scheduledAt=data.scheduledAt?new Date(data.scheduledAt).toISOString():null;await api(c?root()+`/campaigns/${c.id}`:root()+'/campaigns',{method:c?'PATCH':'POST',body:data});await loadCampaigns()},'large');if(c)attachCampaignActions(wrap,c)}
function campaignDetails(c){const deliveries=c.deliveries||[];return `<div class="campaign-detail"><section><span class="eyebrow">${segmentLabels[c.segment]||esc(c.segment)}</span><h2>${esc(c.name)}</h2><div class="message-preview">${esc(c.message).replace(/\n/g,'<br>')}</div><div class="campaign-summary"><span><small>Статус</small><b>${campaignStatusLabels[c.status]||c.status}</b></span><span><small>Аудитория</small><b>${Number(c.metrics?.targeted||0)}</b></span><span><small>Доставлено</small><b>${Number(c.metrics?.sent||0)}</b></span><span><small>Ошибки</small><b>${Number(c.metrics?.failed||0)}</b></span></div></section><section><h3>Журнал доставки</h3><div class="delivery-list">${deliveries.length?deliveries.map(d=>`<div><span><b>${esc(d.telegramId)}</b><small>${new Date(d.createdAt).toLocaleString('ru-RU')}</small></span><i class="status ${d.status==='failed'?'status-failed':'status-sent'}">${d.status==='sent'?'Доставлено':'Ошибка'}</i>${d.reason?`<small>${esc(d.reason)}</small>`:''}</div>`).join(''):'<p class="muted">Отправок ещё не было.</p>'}</div></section></div>`}
function attachCampaignActions(wrap,c){const footer=wrap.querySelector('.modal-actions');if(!footer)return;if(['draft','scheduled','failed'].includes(c.status)){const send=document.createElement('button');send.type='button';send.className='primary';send.textContent='Отправить сейчас';send.onclick=async()=>{if(confirm('Запустить рассылку сейчас?')){send.disabled=true;send.textContent='Отправка…';try{await api(root()+`/campaigns/${c.id}/send`,{method:'POST'});wrap.remove();await loadCampaigns();render()}catch(err){alert(err.message);send.disabled=false;send.textContent='Отправить сейчас'}}};footer.prepend(send)}if(['draft','scheduled','failed'].includes(c.status)){const cancel=document.createElement('button');cancel.type='button';cancel.className='ghost danger';cancel.textContent='Отменить кампанию';cancel.onclick=async()=>{if(confirm('Отменить кампанию?')){await api(root()+`/campaigns/${c.id}`,{method:'PATCH',body:{status:'cancelled'}});wrap.remove();await loadCampaigns();render()}};footer.prepend(cancel)}}
async function openCampaign(id){const c=await api(root()+`/campaigns/${id}`);openCampaignEditor(c)}
function bindCampaigns(){document.querySelector('#new-campaign').onclick=()=>openCampaignEditor();document.querySelector('#refresh-campaigns').onclick=async()=>{await loadCampaigns();render()};document.querySelector('#campaign-status').onchange=e=>{state.campaignStatus=e.target.value;render()};document.querySelectorAll('[data-campaign]').forEach(el=>el.onclick=()=>openCampaign(el.dataset.campaign))}


async function loadAnalytics(){state.analytics=await api(root()+`/analytics?days=${state.analyticsDays}`)}
const rub=value=>Number(value||0).toLocaleString('ru-RU')+' ₽';
function sparkline(series,key){const values=series.map(x=>Number(x[key]||0)),max=Math.max(1,...values);return `<div class="sparkline">${values.map((v,i)=>`<i title="${esc(series[i].date)}: ${v}" style="height:${Math.max(4,v/max*100)}%"></i>`).join('')}</div>`}
function analyticsPage(){const a=state.analytics;if(!a)return `<div class="panel empty"><h3>Загрузка аналитики…</h3></div>`;const m=a.metrics,maxFunnel=Math.max(1,...a.funnel.map(x=>x.value));return `<div class="analytics-toolbar"><div><span class="eyebrow">BUSINESS INTELLIGENCE</span><h2>Единая аналитика магазина</h2><p>Заказы, выручка, воронка, товары, источники и эффективность коммуникаций.</p></div><select id="analytics-days"><option value="7" ${state.analyticsDays===7?'selected':''}>7 дней</option><option value="30" ${state.analyticsDays===30?'selected':''}>30 дней</option><option value="90" ${state.analyticsDays===90?'selected':''}>90 дней</option><option value="365" ${state.analyticsDays===365?'selected':''}>365 дней</option></select></div><div class="analytics-kpis">${[['Выручка',rub(m.revenue),'Оплаченные заказы'],['Заказы',m.orders,'Без отмен и возвратов'],['Средний чек',rub(m.averageOrder),'По действительным заказам'],['Конверсия',m.conversion+'%','Заказы / визиты'],['Новые клиенты',m.newCustomers,'За весь период'],['Повторные',m.repeatCustomers,'Два заказа и больше']].map(([l,v,s])=>`<article class="panel"><small>${l}</small><strong>${v}</strong><span>${s}</span></article>`).join('')}</div><div class="analytics-grid"><section class="panel analytics-chart"><div class="panel-head"><div><small>ДИНАМИКА</small><h3>Выручка и заказы</h3></div></div>${sparkline(a.series,'revenue')}<div class="chart-legend"><span>Выручка: ${rub(m.revenue)}</span><span>Заказов: ${m.orders}</span><span>Визитов: ${m.visits}</span></div></section><section class="panel"><div class="panel-head"><div><small>ВОРОНКА</small><h3>Путь покупателя</h3></div></div><div class="funnel">${a.funnel.map((x,i)=>`<div><span>${esc(x.label)} <b>${x.value}</b></span><i style="width:${Math.max(3,x.value/maxFunnel*100)}%"></i>${i?`<small>${a.funnel[i-1].value?Math.round(x.value/a.funnel[i-1].value*100):0}% от прошлого этапа</small>`:''}</div>`).join('')}</div></section><section class="panel"><div class="panel-head"><div><small>ТОВАРЫ</small><h3>Лидеры продаж</h3></div></div><div class="analytics-list">${a.topProducts.length?a.topProducts.map((p,i)=>`<div><span><b>${i+1}. ${esc(p.name)}</b><small>${p.quantity} шт.</small></span><strong>${rub(p.revenue)}</strong></div>`).join(''):'<p class="muted">Продаж пока нет.</p>'}</div></section><section class="panel"><div class="panel-head"><div><small>ИСТОЧНИКИ</small><h3>Каналы заказов</h3></div></div><div class="analytics-list">${a.sources.length?a.sources.map(s=>`<div><span><b>${esc(s.source)}</b><small>${s.visits||0} визитов · ${s.orders||0} заказов</small></span><strong>${rub(s.revenue||0)}</strong></div>`).join(''):'<p class="muted">Источники пока не определены.</p>'}</div></section><section class="panel comm-card"><div><small>КАМПАНИИ</small><strong>${a.campaigns.sent}</strong><span>доставлено из ${a.campaigns.targeted}</span></div><div><small>ОШИБКИ</small><strong>${a.campaigns.failed}</strong><span>${a.campaigns.campaigns} кампаний</span></div></section><section class="panel comm-card"><div><small>АВТОМАТИЗАЦИИ</small><strong>${a.automations.sent}</strong><span>успешных запусков</span></div><div><small>ОЧЕРЕДЬ / ОШИБКИ</small><strong>${a.automations.pending} / ${a.automations.failed}</strong><span>${a.automations.rules} сценариев</span></div></section></div>`}
function bindAnalytics(){document.querySelector('#analytics-days').onchange=async e=>{state.analyticsDays=Number(e.target.value);await loadAnalytics();render()}}


async function loadPayments(){state.payments=await api(root()+'/payments?status='+encodeURIComponent(state.paymentStatus))}
function paymentsPage(){return `<div class="toolbar"><div><span class="eyebrow">PAYMENTS CORE</span><h2>Платежи</h2></div><select id="payment-status"><option value="all">Все статусы</option>${['pending','authorized','paid','cancelled','expired','refunded','failed'].map(x=>`<option value="${x}" ${state.paymentStatus===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="panel table"><div class="row head"><span>Платёж</span><span>Провайдер</span><span>Сумма</span><span>Статус</span></div>${state.payments.map(p=>`<div class="row"><span><b>${esc(p.id)}</b><small>Заказ ${esc(p.orderId)}</small></span><span>${esc(p.provider)}</span><span>${Number(p.amount||0).toLocaleString('ru-RU')} ${esc(p.currency||'RUB')}</span><span><i class="status ${esc(p.status)}">${esc(p.status)}</i></span></div>`).join('')||'<p class="muted">Платежей пока нет.</p>'}</div>`}
function bindPayments(){const el=document.querySelector('#payment-status');if(el)el.onchange=async e=>{state.paymentStatus=e.target.value;await loadPayments();render()}}
async function loadWarehouse(){if(!state.shop)return;[state.inventory,state.warehouseMetrics,state.warehouseMovements]=await Promise.all([api(root()+'/warehouse/inventory'),api(root()+'/warehouse/metrics'),api(root()+'/warehouse/movements?type='+state.warehouseType)])}
function warehousePage(){const m=state.warehouseMetrics||{skuCount:0,totalStock:0,available:0,lowStock:0,outOfStock:0};return `<div class="toolbar"><div><span class="eyebrow">WAREHOUSE CORE</span><h2>Склад и остатки</h2></div><button class="primary" id="warehouse-adjust">Корректировка</button></div><div class="metrics">${[['SKU',m.skuCount,'Учётных позиций'],['Всего',m.totalStock,'Физический остаток'],['Доступно',m.available,'Можно продать'],['Низкий остаток',m.lowStock,'Не более 3 единиц']].map(([a,b,c])=>`<article><small>${a}</small><strong>${b}</strong><span>${c}</span></article>`).join('')}</div><div class="panel table"><div class="row head"><span>Товар</span><span>SKU</span><span>Остаток</span><span>Доступно</span></div>${state.inventory.map(x=>`<div class="row"><span><b>${esc(x.name)}</b><small>${esc(x.variantName||'Основной')}</small></span><span class="mono">${esc(x.sku)}</span><span>${x.stock}</span><span><i class="status">${x.available}</i></span></div>`).join('')||'<p class="muted">Складских позиций пока нет.</p>'}</div><div class="toolbar"><h3>Последние движения</h3><select id="warehouse-type"><option value="all">Все типы</option>${['receipt','writeoff','transfer','stocktake','sale','return'].map(x=>`<option value="${x}" ${state.warehouseType===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="panel table"><div class="row head"><span>Дата</span><span>SKU</span><span>Тип</span><span>Изменение</span></div>${state.warehouseMovements.slice(0,50).map(x=>`<div class="row"><span>${new Date(x.createdAt).toLocaleString('ru-RU')}</span><span class="mono">${esc(x.sku)}</span><span>${esc(x.type)}</span><span>${x.delta>0?'+':''}${x.delta}</span></div>`).join('')||'<p class="muted">Движений пока нет.</p>'}</div>`}
function bindWarehouse(){const type=document.querySelector('#warehouse-type');if(type)type.onchange=async e=>{state.warehouseType=e.target.value;await loadWarehouse();render()};const button=document.querySelector('#warehouse-adjust');if(button)button.onclick=()=>modal('Корректировка остатка',`<label>Позиция<select name="key">${state.inventory.map(x=>`<option value="${x.productId}|${x.variantId||''}">${esc(x.name)} — ${esc(x.sku)}</option>`).join('')}</select></label><label>Изменение<input name="delta" type="number" required placeholder="10 или -3"></label><label class="full">Причина<input name="reason" required value="Ручная корректировка"></label>`,async form=>{const data=Object.fromEntries(new FormData(form));const [productId,variantId]=String(data.key).split('|');await api(root()+'/warehouse/adjust',{method:'POST',body:{productId,variantId:variantId||null,delta:Number(data.delta),reason:data.reason}});await Promise.all([loadWarehouse(),loadCatalog()]);render()})}

async function loadTeam(){state.team=await api(`/workspaces/${state.workspace.id}/team`)}
function teamPage(){const t=state.team||{members:[],invites:[]};return `<div class="toolbar"><div><span class="eyebrow">ACCESS CONTROL</span><h2>Команда и доступы</h2></div><button class="primary" id="invite-member">+ Пригласить</button></div><div class="panel table"><div class="row head"><span>Сотрудник</span><span>Роль</span><span>Магазины</span><span></span></div>${t.members.map(m=>`<div class="row"><span><b>${esc(m.user?.name||'')}</b><small>${esc(m.user?.email||'')}</small></span><span><i class="status">${esc(m.role)}</i></span><span>${m.role==='owner'||m.role==='admin'?'Все магазины':(m.shops||[]).map(s=>esc(s.name)).join(', ')||'Нет доступа'}</span><span>${m.role==='owner'?'':`<button class="icon-btn danger" data-remove-member="${m.id}">×</button>`}</span></div>`).join('')}</div><div class="panel"><div class="panel-head"><h3>Ожидают принятия</h3></div>${t.invites.filter(i=>i.status==='pending').map(i=>`<p><b>${esc(i.email)}</b> · ${esc(i.role)} · до ${new Date(i.expiresAt).toLocaleDateString('ru-RU')}</p>`).join('')||'<p class="muted">Активных приглашений нет.</p>'}</div>`}
function bindTeam(){document.querySelector('#invite-member').onclick=()=>modal('Пригласить сотрудника',`<label>Email<input name="email" type="email" required></label><label>Роль<select name="role"><option value="viewer">Наблюдатель</option><option value="manager">Менеджер</option><option value="admin">Администратор</option></select></label><label class="full">Магазины<select name="shopIds" multiple>${state.shops.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></label>`,async form=>{const fd=new FormData(form);await api(`/workspaces/${state.workspace.id}/team/invites`,{method:'POST',body:{email:fd.get('email'),role:fd.get('role'),shopIds:fd.getAll('shopIds')}});await loadTeam();render()});document.querySelectorAll('[data-remove-member]').forEach(b=>b.onclick=async()=>{if(confirm('Удалить сотрудника?')){await api(`/workspaces/${state.workspace.id}/team/${b.dataset.removeMember}`,{method:'DELETE'});await loadTeam();render()}});const sw=document.querySelector('#shop-switcher');if(sw)sw.onchange=async e=>{state.shop=state.shops.find(s=>s.id===e.target.value);await Promise.all([loadCatalog(),loadOrders(),loadCustomers(),loadCampaigns()]);render()}}

async function loadStorefront(){[state.storefront,state.versions,state.themePresets]=await Promise.all([api(root()+'/storefront'),api(root()+'/storefront/versions'),api('/storefront/theme-presets')])}
const blockNames={hero:'Баннер',categories:'Категории',products:'Товары',text:'Текст',spacer:'Отступ'};
function blockPreview(block){const x=block.settings||{};if(block.type==='hero')return `<section class="sf-hero"><small>${esc(x.eyebrow||'КОЛЛЕКЦИЯ')}</small><h2>${esc(x.title||state.shop.name)}</h2><p>${esc(x.subtitle||'')}</p><button>${esc(x.buttonText||'Открыть каталог')}</button></section>`;if(block.type==='categories')return `<section><h3>${esc(x.title||'Категории')}</h3><div class="sf-cats">${state.categories.slice(0,4).map(c=>`<span>${esc(c.name)}</span>`).join('')||'<span>Категория</span><span>Категория</span>'}</div></section>`;if(block.type==='products')return `<section><h3>${esc(x.title||'Товары')}</h3><div class="sf-products">${state.products.slice(0,4).map(p=>`<article>${mediaUrl(p.images?.[0]?.url||p.imageUrl)?`<img src="${esc(mediaUrl(p.images?.[0]?.url||p.imageUrl))}">`:'<div class="sf-img">◇</div>'}<b>${esc(p.name)}</b><small>${Number(p.price||0).toLocaleString('ru-RU')} ₽</small></article>`).join('')||'<article><div class="sf-img">◇</div><b>Товар</b><small>0 ₽</small></article>'}</div></section>`;if(block.type==='text')return `<section><h3>${esc(x.title||'Заголовок')}</h3><p>${esc(x.text||'Текстовый блок витрины')}</p></section>`;return `<div style="height:${Number(x.height||32)}px"></div>`}
function storefrontBuilder(){const d=state.storefront;if(!d)return `<div class="panel empty"><h3>Загрузка конструктора…</h3></div>`;const t=d.theme||{};return `<div class="builder-toolbar"><div><b>Theme Builder 2.0</b><p>Настройте фирменный стиль, сетку и компоненты без кода.</p></div><div><button class="ghost" id="save-storefront">Сохранить</button><button class="primary" id="publish-storefront">Опубликовать</button></div></div><div class="theme-presets">${state.themePresets.map(p=>`<button data-theme-preset="${p.id}"><i style="background:${esc(p.theme.accent)}"></i><span><b>${esc(p.name)}</b><small>${esc(p.theme.cardStyle)} · ${esc(p.theme.headerStyle)}</small></span></button>`).join('')}</div><div class="builder-grid"><aside class="panel block-library"><h3>Блоки</h3>${Object.entries(blockNames).map(([type,name])=>`<button data-add-block="${type}">+ ${name}</button>`).join('')}<hr><h3>Палитра</h3>${[['accent','Акцент'],['background','Фон'],['surface','Карточки'],['text','Текст'],['muted','Вторичный текст']].map(([k,l])=>`<label>${l}<input data-theme-color="${k}" type="color" value="${esc(t[k]||'#ffffff')}"></label>`).join('')}<label>Скругление <span id="radius-value">${Number(t.radius||20)} px</span><input id="sf-radius" type="range" min="0" max="40" value="${Number(t.radius||20)}"></label><label>Ширина контента<input id="sf-container" type="range" min="760" max="1440" step="20" value="${Number(t.container||1100)}"></label><label>Шрифт<select id="sf-font">${['Inter','Arial','Georgia','system-ui'].map(x=>`<option ${t.font===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Карточки<select id="sf-card-style">${[['soft','Мягкие тени'],['bordered','Контур'],['flat','Плоские']].map(([v,l])=>`<option value="${v}" ${t.cardStyle===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Кнопки<select id="sf-button-style">${[['filled','Заливка'],['outline','Контур'],['pill','Капсула']].map(([v,l])=>`<option value="${v}" ${t.buttonStyle===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Шапка<select id="sf-header-style">${[['glass','Стекло'],['solid','Сплошная'],['minimal','Минимальная']].map(([v,l])=>`<option value="${v}" ${t.headerStyle===v?'selected':''}>${l}</option>`).join('')}</select></label><hr><h3>Версии</h3><div class="version-list">${state.versions.map(v=>`<button data-restore="${v.id}">Версия ${v.number}<small>${new Date(v.createdAt).toLocaleString('ru-RU')}</small></button>`).join('')||'<p class="muted">Публикаций пока нет</p>'}</div></aside><section class="panel canvas-panel"><div class="phone-frame theme-preview card-${esc(t.cardStyle||'soft')} button-${esc(t.buttonStyle||'filled')} header-${esc(t.headerStyle||'glass')}" style="--accent:${esc(t.accent||'#d59a55')};--radius:${Number(t.radius||20)}px;--sf-bg:${esc(t.background||'#f4f1eb')};--sf-surface:${esc(t.surface||'#fff')};--sf-text:${esc(t.text||'#171717')};--sf-muted:${esc(t.muted||'#777')};font-family:${esc(t.font||'Inter')}"><div class="phone-top">${esc(state.shop.name)} <span>•••</span></div><div id="sf-canvas">${d.blocks.filter(b=>b.visible!==false).map((b,i)=>`<div class="canvas-block" data-block="${i}">${blockPreview(b)}<div class="block-actions"><button data-up="${i}" ${i===0?'disabled':''}>↑</button><button data-down="${i}" ${i===d.blocks.length-1?'disabled':''}>↓</button><button data-edit-block="${i}">✎</button><button data-remove-block="${i}">×</button></div></div>`).join('')}</div></div></section><aside class="panel inspector"><h3>Настройки страницы</h3><label>SEO-заголовок<input id="sf-title" value="${esc(d.seo?.title||'')}"></label><label>Описание<textarea id="sf-description">${esc(d.seo?.description||'')}</textarea></label><div class="theme-summary"><b>Текущая тема</b><span>${esc(t.font||'Inter')}</span><span>${Number(t.container||1100)} px</span><span>${esc(t.cardStyle||'soft')}</span></div><p class="muted">Публичная ссылка после публикации:</p><code>http://127.0.0.1:4174/?shop=${esc(state.shop.slug)}</code></aside></div>`}
function bindStorefront(){const d=state.storefront;document.querySelectorAll('[data-theme-preset]').forEach(btn=>btn.onclick=()=>{const preset=state.themePresets.find(x=>x.id===btn.dataset.themePreset);if(preset){d.theme=structuredClone(preset.theme);render()}});document.querySelectorAll('[data-theme-color]').forEach(input=>input.oninput=e=>{d.theme[e.target.dataset.themeColor]=e.target.value;render()});document.querySelectorAll('[data-add-block]').forEach(btn=>btn.onclick=()=>{const type=btn.dataset.addBlock;d.blocks.push({id:crypto.randomUUID(),type,visible:true,settings:type==='text'?{title:'Новый блок',text:'Добавьте описание'}:type==='spacer'?{height:32}:{title:blockNames[type]}});render()});document.querySelectorAll('[data-remove-block]').forEach(btn=>btn.onclick=()=>{d.blocks.splice(Number(btn.dataset.removeBlock),1);render()});document.querySelectorAll('[data-up]').forEach(btn=>btn.onclick=()=>{const i=Number(btn.dataset.up);[d.blocks[i-1],d.blocks[i]]=[d.blocks[i],d.blocks[i-1]];render()});document.querySelectorAll('[data-down]').forEach(btn=>btn.onclick=()=>{const i=Number(btn.dataset.down);[d.blocks[i+1],d.blocks[i]]=[d.blocks[i],d.blocks[i+1]];render()});document.querySelectorAll('[data-edit-block]').forEach(btn=>btn.onclick=()=>editBlock(Number(btn.dataset.editBlock)));document.querySelector('#sf-radius').oninput=e=>{d.theme.radius=Number(e.target.value);render()};document.querySelector('#sf-container').oninput=e=>{d.theme.container=Number(e.target.value)};document.querySelector('#sf-font').onchange=e=>{d.theme.font=e.target.value;render()};document.querySelector('#sf-card-style').onchange=e=>{d.theme.cardStyle=e.target.value;render()};document.querySelector('#sf-button-style').onchange=e=>{d.theme.buttonStyle=e.target.value;render()};document.querySelector('#sf-header-style').onchange=e=>{d.theme.headerStyle=e.target.value;render()};document.querySelector('#sf-title').oninput=e=>d.seo.title=e.target.value;document.querySelector('#sf-description').oninput=e=>d.seo.description=e.target.value;document.querySelector('#save-storefront').onclick=async()=>{await api(root()+'/storefront',{method:'PATCH',body:d});alert('Черновик сохранён')};document.querySelector('#publish-storefront').onclick=async()=>{await api(root()+'/storefront',{method:'PATCH',body:d});const result=await api(root()+'/storefront/publish',{method:'POST'});state.versions=await api(root()+'/storefront/versions');alert(`Опубликована версия ${result.version}`);render()};document.querySelectorAll('[data-restore]').forEach(btn=>btn.onclick=async()=>{if(confirm('Восстановить эту версию в черновик?')){state.storefront=await api(root()+`/storefront/versions/${btn.dataset.restore}/restore`,{method:'POST'});render()}})}
function editBlock(index){const b=state.storefront.blocks[index],s=b.settings||{};const fields=b.type==='hero'?`<label>Надзаголовок<input name="eyebrow" value="${esc(s.eyebrow||'')}"></label><label>Заголовок<input name="title" value="${esc(s.title||'')}"></label><label>Подзаголовок<textarea name="subtitle">${esc(s.subtitle||'')}</textarea></label><label>Текст кнопки<input name="buttonText" value="${esc(s.buttonText||'')}"></label>`:b.type==='text'?`<label>Заголовок<input name="title" value="${esc(s.title||'')}"></label><label>Текст<textarea name="text">${esc(s.text||'')}</textarea></label>`:b.type==='spacer'?`<label>Высота<input type="number" name="height" min="8" max="200" value="${Number(s.height||32)}"></label>`:`<label>Заголовок<input name="title" value="${esc(s.title||'')}"></label>${b.type==='products'?`<label>Лимит<input type="number" name="limit" min="1" max="20" value="${Number(s.limit||8)}"></label>`:''}`;modal(`Блок: ${blockNames[b.type]}`,fields,async form=>{b.settings=Object.fromEntries(new FormData(form));render()})}

session.token?load():login();

async function loadDelivery(){if(!state.shop)return;[state.deliveryMethods,state.shipments]=await Promise.all([api(root()+'/delivery/methods'),api(root()+'/delivery/shipments')])}
function deliveryPage(){return `<div class="toolbar"><div><span class="eyebrow">DELIVERY CORE</span><h2>Доставка и отправления</h2></div><button class="primary" id="delivery-add">Добавить способ</button></div><div class="panel table"><div class="row head"><span>Способ</span><span>Провайдер</span><span>Стоимость</span><span>Статус</span></div>${state.deliveryMethods.map(x=>`<div class="row"><span><b>${esc(x.name)}</b><small>${esc(x.description||'')}</small></span><span>${esc(x.provider)}</span><span>${Number(x.price||0).toLocaleString('ru-RU')} ₽</span><span><i class="status ${x.active?'paid':'cancelled'}">${x.active?'активен':'выключен'}</i></span></div>`).join('')||'<p class="muted">Используются стандартные способы: самовывоз и курьер.</p>'}</div><div class="toolbar"><h3>Отправления</h3></div><div class="panel table"><div class="row head"><span>Отправление</span><span>Заказ</span><span>Провайдер</span><span>Статус</span></div>${state.shipments.map(x=>`<div class="row"><span><b>${esc(x.id)}</b><small>${esc(x.trackingNumber||'Без трек-номера')}</small></span><span>${esc(x.orderId)}</span><span>${esc(x.provider)}</span><span><i class="status">${esc(x.status)}</i></span></div>`).join('')||'<p class="muted">Отправлений пока нет.</p>'}</div>`}
function bindDelivery(){const button=document.querySelector('#delivery-add');if(button)button.onclick=()=>modal('Новый способ доставки',`<label>Название<input name="name" required value="Курьер"></label><label>Провайдер<select name="provider"><option value="pickup">Самовывоз</option><option value="courier">Курьер магазина</option><option value="cdek">СДЭК</option><option value="boxberry">Boxberry</option><option value="russian_post">Почта России</option></select></label><label>Стоимость<input name="price" type="number" min="0" value="350"></label><label>Бесплатно от<input name="freeFrom" type="number" min="0"></label><label class="full">Описание<input name="description" value="Доставка заказа"></label>`,async form=>{const data=Object.fromEntries(new FormData(form));await api(root()+'/delivery/methods',{method:'POST',body:{...data,price:Number(data.price),freeFrom:data.freeFrom?Number(data.freeFrom):null,active:true}});await loadDelivery();render()})}
